import{_ as s,l as i,o as a,c as n,v as o,p as l,x as r,d as c,i as d,S as f}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"fork","description":"","frontmatter":{"title":"fork","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fork.md","filePath":"cs/fork.md","lastUpdated":1789023840000}'),p={name:"cs/fork.md"};function h(m,e,k,_,P,u){const t=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="fork" tabindex="-1">fork <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;fork&quot;">​</a></h1><div class="epigraph"><p>fork 把当前进程复制成子进程：子返回 0，父返回子的 PID；其后二者独立调度，默认共享打开文件表的引用。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Ritchie and Thompson, The UNIX Time-Sharing System 整理</footer></div><p><a href="/cs/pcb-task-struct">上一课</a>给出可分配的 PCB。用户要再跑一份程序，不能自己写一块内核对象。<a href="/cs/syscall-abi">系统调用 ABI</a> 已有陷入约定。缺口是 Unix 的创建原语：<strong>fork</strong>——复制当前映像，一次调用两个返回。本课不把写时复制的页表细节写完，那是更后的 <a href="/cs/cow-fork">cow-fork</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有「从文件加载新进程」，交互式 shell 无法在保留打开终端的同时换掉地址空间。fork 先克隆：子继承寄存器（除返回值）、页表（逻辑副本）、文件描述符。父继续原来的流。缺口不是新的 PCB 字段清单，而是这一调用的语义：谁返回什么、哪些资源共享引用计数、哪些必须真复制。</p><p><span class="marginnote">子进程地址空间在逻辑上独立：子写自己的栈不应改父的栈。实现上先共享只读页再在写时拆，是 cow 课；本课语义当立即独立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>系统调用：分配新 PCB 与新 PID，复制或共享内存描述符、文件表（引用 +1）、信号掩码。子的 trapframe 从父拷来，把返回值槽写成 0；父的返回值是子 PID。子被放进就绪队列。失败则父得到错误，不存在「半个进程」。</p>',8)),(a(),l(f,null,{default:r(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%88%B6%20PCB%22%5D%20--%3E%20F%5B%22fork%22%5D%0A%20%20F%20--%3E%20P2%5B%22%E7%88%B6%3A%20%E8%BF%94%E5%9B%9E%E5%AD%90%20PID%22%5D%0A%20%20F%20--%3E%20C%5B%22%E5%AD%90%20PCB%3A%20%E8%BF%94%E5%9B%9E%200%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>多线程进程里 fork 只复制调用线程，POSIX 有规定；主干承认这一点，不背手册全文。内核线程一般不对外 fork。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>fork 把「创建」从「加载程序」拆开：先有两份映像，再用下一课 <code>execve</code> 把其中一份换成新程序。shell 的典型路径正是 fork 后子 exec、父 wait。返回值约定让同一份用户代码用 <code>if</code> 分成两路，不必两套入口。</p><p>复制页表根但不复制全部物理页，是性能；语义仍是独立地址空间。<a href="/cs/paging-vm">分页</a> 的权限位稍后在 cow 课改写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论 <code>vfork</code> 的暂停父进程优化当主路径，不把容器里 PID 映射写完。也不把 fork 炸弹当成习题去构造；资源限制是策略。<code>clone</code> 的细粒度标志是线程课。</p><p>后课默认：子是父的副本，返回值不同。子要换成另一个二进制，下一课讲 <code>execve</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fork 复制 PCB 与地址空间语义；父得 PID，子得 0。</li><li>文件表常共享引用；页的写时复制是后课。</li><li>用新程序覆盖映像是 <code>execve</code>。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Ritchie and Thompson, <em>CACM</em> 1974。</li></ul>',9))])}const b=s(p,[["render",h]]);export{T as __pageData,b as default};
